return ['domain'=>'tickets-passes-for-woocommerce','plural-forms'=>'nplurals=2; plural=(n != 1);','language'=>'da_DK','project-id-version'=>'Tickets & Passes for WooCommerce 1.3.0','pot-creation-date'=>'2026-09-14T21:26:30+00:00','po-revision-date'=>'2026-09-15 02:55+0200','x-generator'=>'Cursor','messages'=>['Tickets & Passes for WooCommerce'=>'Tickets & Passes for WooCommerce','Sell tickets, timeslot bookings and passes with WooCommerce, and check visitors in at the door with a built-in QR scanner.'=>'Sælg billetter, tidsrum bookinger og Pass med WooCommerce, og tjek besøgende ind ved døren med en indbygget QR-scanner.','Magnus V.'=>'Magnus V.','First Name'=>'Fornavn','Last Name'=>'Efternavn','Email'=>'E-mail','Valid from'=>'Gyldig fra','Valid to'=>'Gyldig til','Start'=>'Start','End'=>'Slut','Pass ID'=>'Pass-ID','Ticket ID #%d'=>'Billet-ID #%d','The action could not be completed. Please try again.'=>'Handlingen kunne ikke fuldføres. Prøv igen.','TPFW Product Actions'=>'TPFW-produkthandlinger','Tickets, Timeslot Tickets & Pass\'s'=>'Billetter, tidsrumbilletter og Pass','Create'=>'Opret','Cancel'=>'Annuller','Current user does not have admin privileges'=>'Nuværende bruger har ikke administratorrettigheder','Order ID seems to be missing'=>'Ordre-id ser ud til at mangle','Pass\'s cancelled for order'=>'Passet er annulleret for ordre','Tickets, Timeslot Tickets & Pass\'s created for order'=>'Billetter, Tidsrumbilletter og Pass oprettet til ordre','Analytics'=>'Analyse','The statistics could not be loaded. Please try again.'=>'Statistikken kunne ikke indlæses. Prøv igen.','Checkin'=>'Check-in','January'=>'Januar','February'=>'Februar','March'=>'Marts','April'=>'April','May'=>'Maj','June'=>'Juni','July'=>'Juli','August'=>'August','September'=>'September','October'=>'Oktober','November'=>'November','December'=>'December','The start date seems not to be set'=>'Startdatoen ser ikke ud til at være indstillet','The product id seems not to be set, or not an array'=>'Produkt-id\'et ser ikke ud til at være indstillet, eller ikke et array','Customer ID'=>'Kunde-id','Customer Email'=>'Kundens e-mail','Customer Name'=>'Kundenavn','Product ID'=>'Produkt-ID','Product Name'=>'Produktnavn','Checkin Date'=>'Check-in-dato','There are no check-ins in the selected range to export'=>'Der er ingen Check-in i det valgte område, der skal eksporteres','Successfully fetched all available data, and transformed to a CSV file'=>'Hentede alle tilgængelige data og omdannet til en CSV-fil','The year date seems not to be set'=>'Årets dato ser ikke ud til at være indstillet','The month date seems not to be set'=>'Månedsdatoen ser ikke ud til at være indstillet','The day date seems not to be set'=>'Dagsdatoen ser ikke ud til at være indstillet','The product id seems not to be set or not an array'=>'Produkt-id\'et ser ikke ud til at være indstillet eller ikke et array','Succesful fetched all available data'=>'Succesfuld hentede alle tilgængelige data','Tickets'=>'Billetter','Timeslot Tickets'=>'Tidsrumbilletter','Passes'=>'Pass','Check-ins recorded at the door, day by day and hour by hour.'=>'Check-in optaget i døren, dag for dag og time for time.','Year'=>'År','Products'=>'Produkter','All'=>'Alle','None'=>'Ingen','%1$s of %2$s selected'=>'%1$s af %2$s valgt','Show check-ins'=>'Vis check-in','Check-ins by day'=>'Check-in pr. dag','Select a day to break it down by hour.'=>'Vælg en dag for at opdele den efter time.','Export year'=>'Eksportår','Check-ins'=>'Check-ins','Busiest day'=>'Den travleste dag','Days with check-ins'=>'Dage med check-in','No check-ins were recorded for this year and selection.'=>'Der blev ikke registreret Check-in for dette år og udvælgelse.','Quiet'=>'Stille','Busy'=>'Optaget','Check-ins by hour'=>'Check-in pr. time','Go to date'=>'Gå til dato','Export day'=>'Eksportdag','Select a day above, or pick a date, to see when people arrived.'=>'Vælg en dag ovenfor, eller vælg en dato for at se, hvornår folk ankom.','Nobody checked in on this day.'=>'Ingen tjekkede ind på denne dag.','Scanner / API Settings'=>'Indstillinger for scanner/API','Status %s color is not a valid HEX format color'=>'Status %s farve er ikke en gyldig HEX format farve','Scanner / API Settings have successfully been updated'=>'Scanner/API-indstillinger er blevet opdateret','Timeslot ticket could not be found'=>'Tidsrumbilletten blev ikke fundet','Access denied'=>'Adgang nægtet','Check-in must use POST'=>'Check-in skal bruge POST','Guest Pass could not be found with the given id'=>'Gæstepasset blev ikke fundet med det angivne ID','Parent Pass could not be found with the given id'=>'Det overordnede Pass blev ikke fundet med det angivne ID','Timeslot / Ticket / Pass could not be found with the given id'=>'Tidsrum/billet/Pass blev ikke fundet med det angivne ID','Checks in a ticket, timeslot ticket or pass. One nano id namespace covers all three - the endpoint works out which type the scanned code belongs to.'=>'Tjekker en billet, Tidsrumbillet eller -Pass ind. Et nano ID-navneområde dækker alle tre - slutpunktet finder ud af, hvilken type den scannede kode tilhører.','Scanner role or manage_woocommerce. Optional X-TPFW-Scanner-Token header instead of a password.'=>'Scannerrolle eller manage_woocommerce. Valgfri X-TPFW-Scanner-Token header i stedet for en adgangskode.','Checked in. Body carries sMessage, sType, sHolderName, valid_from, valid_to, max_uses, iUsesRemaining, sPhotoURL (passes) and sHexColor. It does not include the raw database row.'=>'Tjekket ind. Svaret indeholder sMessage, sType, sHolderName, valid_from, valid_to, max_uses, iUsesRemaining, sPhotoURL (pas) og sHexColor. Den omfatter ikke den rå databaserække.','Refused for a reason the door staff needs to read: outside its validity window, on cooldown after a previous scan (iCooldown, iCooldownOver), already at its maximum uses, guest pass before the holder checked in, or being scanned at another door at the same moment. Body carries sMessage and sHexColor.'=>'Afvist af en grund skal dørpersonalet læse: uden for gyldighedsvinduet, ved ventetid efter en tidligere scanning (iventetid, iventetidOver), allerede ved maksimal brug, gæstepas før indehaveren tjekket ind eller ved at blive scannet ved en anden dør på samme tidspunkt. Svaret indeholder sMessage og sHexColor.','No valid credentials, or no ticket, timeslot ticket or pass matches the id.'=>'Ingen gyldige legitimationsoplysninger, eller ingen billet, Tidsrumbillet eller pas matcher id\'et.','The nano id in the path is not shaped like one, so nothing was looked up.'=>'nano ID\'et i stien er ikke formet som et, så der blev ikke slået noget op.','GET is refused and does not check anyone in. Use POST.'=>'GET afvises og tjekker ikke nogen ind. Brug POST.','Checks in a guest pass - a pass issued under a parent pass. Same responses as the endpoint above, plus sPhotoURL on success when the guest has a profile photo.'=>'Tjekker et gæstepass - et kort, der er udstedt under et forældrekort. Samme svar som slutpunktet ovenfor plus sPhotoURL ved succes, når gæsten har et profilbillede.','Checked in. Body carries sMessage, sPhotoURL and sHexColor.'=>'Tjekket ind. Svaret indeholder sMessage, sPhotoURL og sHexColor.','Outside its validity window, on cooldown, at its maximum uses, not yet activated by the holder\'s check-in, or being scanned at another door at the same moment.'=>'Uden for gyldighedsvinduet, ved ventetid, ved maksimal brug, endnu ikke aktiveret ved indehaverens Check-in, eller ved at blive scannet ved en anden dør på samme tidspunkt.','No valid credentials, or the guest pass (or its parent pass) could not be found.'=>'Ingen gyldige legitimationsoplysninger, eller gæstepasset (eller dets overordnede pas) kunne ikke findes.','The 50 most recent check-ins performed by the authenticated scanner account, newest first. Use it to fill a history list in your app. Each entry has sTypeKey (ticket, timeslot, pass or guestpass), sHolderName and sCreatedUTC, an ISO-8601 timestamp carrying the site timezone offset.'=>'De 50 seneste Check-in udført af den godkendte scannerkonto, nyeste først. Brug den til at udfylde en historikliste i din app. Hver post har sTypeKey (billet, tidsrum, pas eller gæstepas), sHolderName og sCreatedUTC, et ISO-8601-tidsstempel, der bærer stedets tidszoneforskydning.','Scanner role or manage_woocommerce'=>'Scannerrolle eller manage_woocommerce','Body carries aHistory, an array of entries. An account that has scanned nothing gets an empty array.'=>'Svaret indeholder aHistory, en række poster. En konto, der ikke har scannet noget, får et tomt array.','No valid credentials.'=>'Ingen gyldige legitimationsoplysninger.','Returns a timeslot ticket as a calendar file. This one is deliberately open: the nano id in the URL is itself the secret, and the confirmation email hands it to the customer so they can add their booking to a calendar on any device.'=>'Returnerer en Tidsrumbillet som en kalenderfil. Denne er bevidst åben: nano ID\'et i URL er i sig selv hemmeligheden, og bekræftelses-e-mailen giver den til kunden, så de kan føje deres booking til en kalender på enhver enhed.','None - the nano id is the secret'=>'Ingen - nano ID\'et er hemmeligheden','A text/calendar file, not JSON.'=>'En tekst-/kalenderfil, ikke JSON.','No timeslot ticket matches the id.'=>'Ingen Tidsrumbillet matcher id\'et.','This is the check-in API external scanner apps use to validate tickets, timeslot tickets and passes.'=>'Dette er check-in API eksterne scannerapps, der bruges til at validere billetter, Tidsrumbilletter og Pass.','Turn the API and the built-in scanner page on or off below, and set the colors returned to the scanner for each scan result.'=>'Slå API og den indbyggede scanner-side til eller fra nedenfor, og indstil farverne, der returneres til scanneren for hvert scanningsresultat.','A note on the built-in scanner'=>'En note om den indbyggede scanner','The check-in page that ships with this plugin does the job: it opens the camera in a browser, decodes the QR code and checks the visitor in. For a small door, or a venue scanning a few hundred people a night, it is all you need.'=>'Den Check-inside, der leveres med dette plugin, gør jobbet: den åbner kameraet i en browser, afkoder QR-koden og tjekker den besøgende ind. For en lille dør eller et sted, der scanner et par hundrede mennesker om natten, er det alt, hvad du har brug for.','It is not the optimal tool, though. A browser page cannot drive a phone the way a native app can: focus and decoding are slower, every single scan needs a live connection, and a locked screen or a switched tab interrupts the camera. If you scan at volume, or at a gate where the signal is poor, a standalone native scanner app will be faster and far more reliable.'=>'Det er dog ikke det optimale værktøj. En browserside kan ikke køre en telefon, som en indfødt app kan: Fokus og afkodning er langsommere, hver eneste scanning har brug for en liveforbindelse, og en låst skærm eller en skiftet fane afbryder kameraet. Hvis du scanner ved lydstyrke eller ved en port, hvor signalet er dårligt, vil en standalone native scanner-app være hurtigere og langt mere pålidelig.','That is what the API is for. Turn it on and any app - one your developer builds, or an existing scanner app that can call a URL - can check tickets, timeslot tickets and passes in against this site. The endpoints are documented below: check-in is an authenticated POST, history and the calendar file are GET.'=>'Det er det, API er til for. Slå den til, og enhver app - en, som din udvikler bygger, eller en eksisterende scannerapp, der kan ringe til en URL - kan tjekke billetter, Tidsrumbilletter og tjekke ind mod dette websted. Endepunkterne er dokumenteret nedenfor: Check-in er en godkendt POST, historik og kalenderfilen er GET.','If you would rather not build it yourself, get in touch on %s and we can see if we can figure something out.'=>'Hvis du hellere ikke vil bygge det selv, så kontakt %s, så kan vi se, om vi kan finde ud af noget.','the plugin support forum'=>'plugin-supportforummet','Enable API'=>'Aktivér API','An API is how an external app - like a scanner app on your door staff\'s phones - talks to this site to check tickets in and out. Turn this on only if something outside this site needs to call the check-in endpoints; the built-in scanner below works without it.'=>'En API er, hvordan en ekstern app - som en scannerapp på dine dørpersonales telefoner - taler til dette websted for at tjekke billetter ind og ud. Slå kun dette til, hvis noget uden for dette websted skal ringe til check-in-slutpunkterne; den indbyggede scanner nedenfor fungerer uden den.','API endpoint reference'=>'Reference til API-slutpunkter','Base URL'=>'Basis-URL','Every path below is relative to that. Check-in is POST. History is GET. The calendar file is GET and is not JSON.'=>'Hver sti nedenfor er i forhold til det. Check-in er POST. Historik er GET. Kalenderfilen er GET og er ikke JSON.','Authentication'=>'Godkendelse','HTTP Basic authentication with a WordPress account on this site that holds the Scanner role, or any account that can manage WooCommerce. Create one account per device so the check-in history tells you which door did what. External apps may send X-TPFW-Scanner-Token instead of a password; tokens can be revoked without changing the WordPress user password.'=>'HTTP Grundlæggende godkendelse med en WordPress-konto på dette websted, der har scannerrollen, eller enhver konto, der kan administrere WooCommerce. Opret én konto pr. enhed, så Check-inhistorikken fortæller dig, hvilken dør der gjorde hvad. Eksterne apps kan sende X-TPFW-Scanner-Token i stedet for en adgangskode; tokens kan tilbagekaldes uden at ændre WordPress-brugeradgangskoden.','Use an Application Password rather than the real account password - WordPress generates them under Users, they only work for API requests and can be revoked one at a time. Send requests over HTTPS: Basic authentication puts the credentials in a header on every single request.'=>'Brug en Application Password i stedet for den rigtige kontoadgangskode - WordPress genererer dem under Brugere, de arbejder kun for API-anmodninger og kan tilbagekaldes en ad gangen. Send anmodninger over HTTPS: Basisgodkendelse sætter legitimationsoplysningerne i en header på hver enkelt anmodning.','Outside callers are only accepted while Enable API is on above. The built-in scanner page authenticates with its own login session instead, so it keeps working either way.'=>'Eksterne opkald accepteres kun, mens Aktiver API er slået til ovenfor. Den indbyggede scanner-side autentificerer i stedet med sin egen login-session, så den fortsætter med at fungere uanset hvad.','Endpoints'=>'Slutpunkter','Requires:'=>'Kræver','Result colors'=>'Resultatfarver','Every JSON response carries sHexColor, the color configured above for that outcome. Painting your result screen with it means the colors your staff learn to read are set here, in wp-admin, and not baked into the app.'=>'Hvert JSON-svar bærer sHexColor, den farve, der er konfigureret ovenfor til dette resultat. Hvis du maler din resultatskærm med den, betyder det, at de farver, dit personale lærer at læse, er indstillet her, i wp-admin, og ikke bagt ind i appen.','Example'=>'Eksempel','A nano id is 21 characters of A-Z, a-z and 0-9. The QR code itself contains the full check-in URL for this site (…/scanner/checkin/<nano id>, with /guest appended for a guest pass), so your app can either request that URL directly or take the last path segment and build the request against this site\'s REST base.'=>'Et nano id består af 21 tegn fra A-Z, a-z og 0-9. Selve QR-koden indeholder den fulde URL til check-in på dette websted (…/scanner/checkin/<nano id>, med /guest tilføjet for et gæstepass), så din app kan enten anmode om denne URL direkte eller tage det sidste stisegment og opbygge anmodningen mod dette websteds REST-base.','Enable built-in scanner'=>'Aktivér indbygget scanner','Turns on the check-in page at /check-in/ - a full-screen camera scanner your door staff open on a phone, with no wp-admin around it. They sign in with a WordPress account that has the Scanner role, and a link to it appears in this plugin\'s menu. Leave it off if you check people in with a separate scanner app instead. This toggle is independent of the API above.'=>'Slår Check-insiden på /check-in/ til - en fuldskærms kamerascanner, som dit dørpersonale åbner på en telefon, uden wp-admin omkring den. De logger ind med en WordPress-konto, der har scannerrollen, og et link til den vises i dette plugins menu. Slå det fra, hvis du tjekker personer ind med en separat scannerapp i stedet. Denne knap er uafhængig af API ovenfor.','Successful Check-in (200)'=>'Check-in lykkedes (200)','Color the scanner app should show when a ticket, timeslot ticket or pass is successfully checked in.'=>'Farve på scannerappen skal vise, når en billet, Tidsrumbillet eller Pass er tjekket ind.','Reset to the default color'=>'Nulstil til standardfarven','Not Valid or Already Used (202)'=>'Ikke gyldig eller allerede brugt (202)','Color shown when a scan happens outside its valid time window, on cooldown after a previous scan, or after it has already reached its maximum uses.'=>'Farve vises, når en scanning sker uden for dens gyldige tidsrum, ved ventetid efter en tidligere scanning, eller efter at den allerede har nået sit maksimale anvendelsesområde.','Invalid Request (406)'=>'Ugyldig anmodning (406)','Color shown when the request itself is invalid, e.g. the scanned code doesn\'t match any known ticket, timeslot ticket or pass.'=>'Farve vises, når selve anmodningen er ugyldig, f.eks. matcher den scannede kode ikke nogen kendt billet, Tidsrumbillet eller Pass.','Save Settings'=>'Gem indstillinger','Once per Minute'=>'pr. minut','This action is only allowed for site admins'=>'Denne handling er kun tilladt for webstedsadministratorer','No matching row found for the provided Nano ID'=>'Der blev ikke fundet nogen matchende række for det angivne nano ID','Sent'=>'Sendt','Cancel this item? Its QR code will stop working until it is reset.'=>'Annuller denne artikel? Dens QR-kode stopper med at fungere, indtil den nulstilles.','Reset this item? Its recorded check-ins will be cleared.'=>'Nulstil dette element? Dets registrerede Check-in vil blive ryddet.','Remove this profile photo? The holder will be able to upload a new one.'=>'Vil du fjerne dette profilbillede? Indehaveren vil kunne uploade en ny.','Apply this action to every selected row?'=>'Vil du anvende denne handling på alle valgte rækker?','Transferred'=>'Overført','Nano ID not found'=>'nano ID ikke fundet','User with the given ID, was not found'=>'Bruger med det givne ID, blev ikke fundet','Successfully resent to %s'=>'Videresendt til %s','Order not found'=>'Ordren blev ikke fundet','The product this ticket was bought from no longer exists'=>'Produktet, som denne billet blev købt fra, findes ikke længere','Email Message was empty, so no email was send'=>'E-mailbeskeden var tom, så der blev ikke sendt nogen e-mail','No account was found for that email address or user ID. The new holder needs an account on this site first.'=>'Der blev ikke fundet nogen konto for den pågældende e-mailadresse eller bruger-id. Den nye indehaver skal først have en konto på denne side.','No active row was found for the provided Nano ID'=>'Der blev ikke fundet nogen aktiv række for det angivne nano ID','That account already holds this item.'=>'Denne konto har allerede denne vare.','%1$s %2$s transferred from %3$s to %4$s by %5$s.'=>'%1$s %2$s overført fra %3$s til %4$s af %5$s.','Transferred and emailed to %s'=>'Overført og sendt til %s','Transferred to %1$s, but the email could not be sent: %2$s'=>'Overført til %1$s, men e-mailen kunne ikke sendes: %2$s','Successfully reset'=>'Din adgangskode blev nulstillet','Cancelled'=>'Aflyst','Successfully cancelled'=>'Annulleret','Filter by status'=>'Filtrér efter status','All statuses'=>'Alle statusser','Search'=>'Søg','Filter'=>'Filter','Download CSV (%s row)'=>'Download CSV (%s række)' . "\0" . 'Download CSV (%s rækker)','Reset'=>'Nulstil','%1$d of %2$d selected rows cancelled.'=>'%1$d af %2$d valgte rækker annulleret.','%1$d of %2$d selected rows reset.'=>'%1$d af %2$d valgte rækker nulstilles.','ID'=>'ID','Status'=>'Status','Holder user ID'=>'Bruger-id for indehaver','Holder email'=>'Indehaverens e-mail','Product'=>'Produkt','Order ID'=>'Ordre-ID','Max uses'=>'Max anvendelser','Created'=>'Oprettet den','Used'=>'Brugt','Expired'=>'Udløbet','Not valid yet'=>'Ikke gyldig','Partial'=>'Delvis','Unused'=>'Ubrugt','Download'=>'Download','Transfer'=>'Overføre','Resend'=>'Genafsend','(deleted product)'=>'Slettet produkt','Transfer to another customer'=>'Overfør til en anden kunde','The new holder must already have an account on this site. They will be emailed the QR code, and a note is added to the original order.'=>'Den nye indehaver skal allerede have en konto på dette websted. De vil blive sendt en e-mail med QR-koden, og der tilføjes en note til den oprindelige ordre.','Email address or user ID'=>'E-mailadresse eller bruger-id','Email Settings'=>'E-mailindstillinger','Copied!'=>'Kopieret!','Failed to save settings.'=>'Indstillinger ikke gemt.','Purchased Items'=>'Købte varer','Your QR Code'=>'Din QR-kode','Firstname'=>'Fornavn','Lastname'=>'Efternavn','Add to Calendar'=>'Tilføj til kalenderen','Email Settings have successfully been updated'=>'E-mailindstillinger er blevet opdateret','WooCommerce Order Confirmation'=>'WooCommerce Ordrebekræftelse','Appended to the standard WooCommerce order confirmation email whenever the order contains a ticket, timeslot ticket or pass. The QR codes are not issued yet at this point, so this text cannot show them.'=>'Vedhæftet til standard WooCommerce ordrebekræftelses-e-mailen, når ordren indeholder en billet, Tidsrumbillet eller -pas. QR-koderne er endnu ikke udstedt, så denne tekst kan ikke vise dem.','WooCommerce Completed Order'=>'WooCommerce Gennemført ordre','Appended to the WooCommerce completed order email whenever the order contains a ticket, timeslot ticket or pass. This is the first email that carries the QR codes, which are listed below this text.'=>'Vedhæftet til den udfyldte WooCommerce-ordre-e-mail, når ordren indeholder en billet, Tidsrumbillet eller -pas. Dette er den første e-mail, der bærer QR-koderne, som er angivet under denne tekst.','Resend Ticket'=>'Send billetten igen','Sent when a customer or admin manually resends a ticket\'s QR code from the order or account dashboard.'=>'Sendt, når en kunde eller administrator manuelt sender en billets QR-kode fra ordre- eller kontokontrolpanelet.','Resend Pass'=>'Send Pass igen','Sent when a customer or admin manually resends a pass\'s QR code from the order or account dashboard.'=>'Sendt, når en kunde eller administrator manuelt sender en Passs QR-kode fra ordre- eller kontokontrolpanelet.','Guest Pass Invite - New User'=>'Gæstepassinvitation - ny bruger','Sent to a guest pass recipient who doesn\'t have an account on this site yet, inviting them to create one.'=>'Sendt til en gæstepassmodtager, der endnu ikke har en konto på dette websted, og inviterer vedkommende til at oprette en.','Guest Pass Invite - Existing User'=>'Gæstepassinvitation - eksisterende bruger','Sent to a guest pass recipient who already has an account on this site.'=>'Sendt til en gæstepassmodtager, der allerede har en konto på dette websted.','These templates control the emails sent automatically alongside your regular WooCommerce order emails.'=>'Disse skabeloner styrer de e-mails, der sendes automatisk sammen med dine almindelige WooCommerce-ordre-e-mails.','Expand a template below to edit its subject and message, and use the tags to insert live details like the customer\'s name or QR code.'=>'Udvid en skabelon nedenfor for at redigere emnet og meddelelsen, og brug tags til at indsætte levende detaljer som kundens navn eller QR-kode.','Toggle panel: %s'=>'Skiftepanel: %s','Subject'=>'Emne','Message'=>'Meddelelse','Available tags - click to insert at your cursor:'=>'Tilgængelige tags - klik for at indsætte ved markøren:','Scanner'=>'Scanner','Missing Nano ID'=>'Manglende nano ID','QR code image does not seem to exist'=>'QR kodebillede ser ikke ud til at eksistere','Ticket / Timeslot with given Nano ID does not seem to exist'=>'Billet/tidsrum med givet nano ID ser ikke ud til at eksistere','The product this ticket belongs to no longer exists'=>'Produktet, som denne billet tilhører, findes ikke længere','QR code image could not be read'=>'QR kodebillede kunne ikke læses','Ticket'=>'Billet','The ticket PDF could not be generated'=>'Billetten PDF kunne ikke genereres','PDF file successfully created and fetched'=>'PDF-filen blev oprettet og hentet','Timeslot Ticket'=>'Tidsrumbillet','Pass with given Nano ID does not seem to exist'=>'Bestået med givet nano ID ser ikke ud til at eksistere','The product this pass belongs to no longer exists'=>'Produktet, som denne Pass tilhører, findes ikke længere','Pass'=>'Pass','Guest Pass'=>'Gæstepass','The pass PDF could not be generated'=>'Passet PDF kunne ikke genereres','General'=>'Generelt','Scanner / API'=>'Scanner/API','Ticket & Passes'=>'Billet og Pass','Ticket ID: %s'=>'Billet-ID: %s','Hi {{customer_name}},'=>'Hej {{customer_name}}','Thanks for your order at {{site_name}}. We will email your QR codes as soon as the order is completed - until then there is nothing you need to do.'=>'Tak for din ordre hos {{site_name}}. Vi e-mailer dine QR-koder, så snart ordren er gennemført - indtil da er der ikke noget, du skal gøre.','Your tickets and passes will also appear under <a href=\\"{{myaccount_url}}\\">My Account</a>.'=>'Dine billetter og Pass vises også under <a href=\\"{{myaccount_url}}\\">Min konto</a>.','Your order at {{site_name}} is complete. Your QR codes are below - have them ready at the door.'=>'Din ordre hos {{site_name}} er gennemført. Dine QR-koder er nedenfor - hav dem klar ved døren.','Y